// Photo registry for the Koh Tao climbing guide.
// GENERATED from work/images/class-*.json (179 guidebook images, classified by page) and
// work/community/web-photos.json (community + trip-report images with author/license).
// Regenerate with work/gen-photos.mjs.
//
// `file` is the path relative to app/public — e.g. images/guide/p12-0-X30.jpg.
// Guide images: `kind` is the classifier label (photo-topo, topo-diagram, action-photo,
// crag-photo, map, scenic, other). Images the classifier marked unusable keep their label
// with an '-unusable' suffix (e.g. 'other-unusable') so the UI can filter them out with
// kind.endsWith('-unusable') — or just use the isUsable() helper below.
// Community images: kind is community-photo (or map for the topo graphic). Entries whose
// license contains "ND" (NoDerivatives) must be shown unmodified — see isNdLicense().
// `sourceUrl` links to the page where the photo was published (for attribution).

export interface PhotoEntry {
  file: string
  kind: string
  caption: string
  crag: string | null
  credit?: string
  license?: string
  sourceUrl?: string
  page?: number
}

