// True for guide images the classifier marked usable. Community images are always usable.
export const isUsable = (p: PhotoEntry) => !p.kind.endsWith('-unusable')

// NoDerivatives licenses forbid cropping/resizing beyond scaling — display unmodified.
export const isNdLicense = (p: PhotoEntry) => (p.license ?? '').includes('ND')

// Exact crag match, also accepting "Crag Name (qualifier)" variants e.g. "Koh Nang Yuan (scenic)".
const cragMatches = (p: PhotoEntry, cragName: string) => p.crag === cragName || (p.crag ?? '').startsWith(cragName + ' (')

export const photosForCrag = (cragName: string) => [...guidePhotos, ...communityPhotos].filter((p) => cragMatches(p, cragName) && isUsable(p))

export const guidePhotosForCrag = (cragName: string) => guidePhotos.filter((p) => cragMatches(p, cragName) && isUsable(p))

export const communityPhotosForCrag = (cragName: string) => communityPhotos.filter((p) => cragMatches(p, cragName))
